$file = "X:\code\copilot-worktrees\P04\cirvine-msft-redesigned-journey\assets\config.txt"
$content = Get-Content -Path $file -Raw
$lines = @($content -split "`n" | Where-Object { $_ -ne "" })

Write-Host "Validating constraints..."
Write-Host "Total lines: $($lines.Count)"

$valid = $true

# Check line count (exactly 12)
if ($lines.Count -ne 12) {
    Write-Host "ERROR: Expected 12 lines, got $($lines.Count)"
    $valid = $false
}

# Check each line
$allowed = @()
$allowed += ([char]'A'..[char]'Z')
$allowed += ([char]'0'..[char]'9')
$allowed += ' ', '+', '|', '/', '\', '_', '*', '.', '#', '(', ')', ':', '=', '-'

$hasConfig = $false
for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    $len = $line.Length

    # Check length (20-48 chars)
    if ($len -lt 20 -or $len -gt 48) {
        Write-Host "ERROR: Line $($i+1) length is $len (expected 20-48)"
        $valid = $false
    }

    # Check for CONFIG
    if ($line -match "CONFIG") {
        $hasConfig = $true
    }

    # Check characters
    foreach ($char in $line.ToCharArray()) {
        if ($allowed -notcontains $char) {
            Write-Host "ERROR: Line $($i+1) contains invalid character: '$char'"
            $valid = $false
            break
        }
    }

    # Check trailing whitespace
    if ($line -match '\s$') {
        Write-Host "ERROR: Line $($i+1) has trailing whitespace"
        $valid = $false
    }

    Write-Host "Line $($i+1): $len chars - $line"
}

if (!$hasConfig) {
    Write-Host "ERROR: File does not contain literal 'CONFIG'"
    $valid = $false
}

# Check file ends with exactly one newline
$bytes = [System.IO.File]::ReadAllBytes($file)
if ($bytes[-1] -eq 10 -and $bytes[-2] -eq 10) {
    Write-Host "ERROR: File ends with multiple newlines"
    $valid = $false
} elseif ($bytes[-1] -ne 10) {
    Write-Host "ERROR: File does not end with newline"
    $valid = $false
}

if ($valid) {
    Write-Host ""
    Write-Host "✓ All constraints validated successfully"
}

