18.         Get-RequiredOption -Options $options -Name 'data-file'
19.     }
20.     else {
21.         $defaultDataFile
22.     }
23.     $asJson = $options.Contains('json')
24. 
25.     switch ($Command.ToLowerInvariant()) {
26.         'add' {
27.             Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json')
28.             $title = Get-RequiredOption -Options $options -Name 'title'
29.             $tasks = @(Read-TaskStore -Path $dataFile)
30.             $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
31.             $task = [ordered]@{
32.                 id = $nextId
33.                 title = $title.Trim()
