64.                 throw '--id must be a positive integer.'
65.             }
66.             $tasks = @(Read-TaskStore -Path $dataFile)
67.             $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
68.             if ($null -eq $task) {
69.                 throw "Task $id was not found."
70.             }
71.             $task.status = 'completed'
72.             Write-TaskStore -Path $dataFile -Tasks $tasks
73.             if ($asJson) {
74.                 Write-TaskForgeOutput -Value $task -AsJson $true
75.             }
76.             else {
77.                 "Completed task $id."
78.             }
79.         }
80.         'remove' {
81.             Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
82.             $idText = Get-RequiredOption -Options $options -Name 'id'
83.             $id = 0
84.             if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
85.                 throw '--id must be a positive integer.'
86.             }
87.             $tasks = @(Read-TaskStore -Path $dataFile)
88.             $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
89.             if ($remaining.Count -eq $tasks.Count) {
90.                 throw "Task $id was not found."
91.             }
92.             Write-TaskStore -Path $dataFile -Tasks $remaining
