1. Set-StrictMode -Version Latest
2. 
3. function Read-TaskStore {
4.     param([Parameter(Mandatory)][string]$Path)
5. 
6.     if (-not (Test-Path -LiteralPath $Path)) {
7.         return @()
8.     }
9. 
10.     $content = Get-Content -LiteralPath $Path -Raw
11.     if ([string]::IsNullOrWhiteSpace($content)) {
12.         return @()
13.     }
14. 
15.     $parsed = ConvertFrom-Json -InputObject $content
16.     return @($parsed)
17. }
18. 
19. function Write-TaskStore {
20.     param(
21.         [Parameter(Mandatory)][string]$Path,
22.         [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
23.     )
24. 
25.     $parent = Split-Path -Parent $Path
26.     if ($parent -and -not (Test-Path -LiteralPath $parent)) {
27.         New-Item -ItemType Directory -Path $parent -Force | Out-Null
28.     }
29. 
30.     $temporary = "$Path.$PID.tmp"
31.     $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
32.     [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
33.     Move-Item -LiteralPath $temporary -Destination $Path -Force
34. }
35. 
36. function ConvertFrom-TaskForgeArguments {
37.     param([AllowEmptyCollection()][string[]]$Arguments)
38. 
39.     $options = [ordered]@{}
40.     for ($index = 0; $index -lt $Arguments.Count; $index++) {
41.         $token = $Arguments[$index]
42.         if (-not $token.StartsWith('--')) {
43.             throw "Unexpected argument: $token"
44.         }
45. 
46.         $name = $token.Substring(2)
47.         if ([string]::IsNullOrWhiteSpace($name)) {
48.             throw 'Option name cannot be empty.'
49.         }
50.         if ($options.Contains($name)) {
51.             throw "Duplicate option: --$name"
52.         }
53. 
54.         if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
55.             $options[$name] = $Arguments[++$index]
56.         }
57.         else {
58.             $options[$name] = $true
59.         }
60.     }
61. 
62.     return $options
63. }
64. 
65. function Get-RequiredOption {
66.     param(
67.         [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
68.         [Parameter(Mandatory)][string]$Name
69.     )
70. 
71.     if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
72.         [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
73.         throw "Missing required option: --$Name"
74.     }
75.     return [string]$Options[$Name]
76. }
77. 
78. function Assert-KnownOptions {
79.     param(
80.         [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
81.         [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
82.     )
83. 
84.     foreach ($name in $Options.Keys) {
85.         if ($name -notin $Allowed) {
86.             throw "Unknown option: --$name"
87.         }
88.     }
89. }
90. 
91. function Write-TaskForgeOutput {
92.     param(
93.         [Parameter(Mandatory)]$Value,
94.         [Parameter(Mandatory)][bool]$AsJson
95.     )
96. 
97.     if ($AsJson) {
98.         ConvertTo-Json -InputObject $Value -Depth 8 -Compress
99.     }
100.     else {
101.         [string]$Value
102.     }
103. }
104. 
105. Export-ModuleMember -Function *
106.

