1. Set-StrictMode -Version Latest
2. 
3. function Read-TaskStore {
4.     param([Parameter(Mandatory)][string]$Path)
5. 
6.     if (-not (Test-Path -LiteralPath $Path)) {
7.         return @()
8.     }
9. 
10.     $content = Get-Content -LiteralPath $Path -Raw
11.     if ([string]::IsNullOrWhiteSpace($content)) {
12.         return @()
13.     }
14. 
15.     $parsed = ConvertFrom-Json -InputObject $content
16.     return @($parsed)
17. }
18. 
19. function Write-TaskStore {
20.     param(
21.         [Parameter(Mandatory)][string]$Path,
22.         [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
23.     )
24. 
25.     $parent = Split-Path -Parent $Path
26.     if ($parent -and -not (Test-Path -LiteralPath $parent)) {
27.         New-Item -ItemType Directory -Path $parent -Force | Out-Null
28.     }
29. 
30.     $temporary = "$Path.$PID.tmp"
31.     $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
32.     [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
33.     Move-Item -LiteralPath $temporary -Destination $Path -Force
34. }
35. 
36. function Read-TaskForgeConfig {
37.     param([Parameter(Mandatory)][string]$Path)
38. 
39.     if (-not (Test-Path -LiteralPath $Path)) {
40.         return [ordered]@{}
41.     }
42. 
43.     $content = Get-Content -LiteralPath $Path -Raw
44.     if ([string]::IsNullOrWhiteSpace($content)) {
45.         return [ordered]@{}
46.     }
47. 
48.     $config = ConvertFrom-Json -InputObject $content -AsHashtable
49.     if ($config -isnot [System.Collections.IDictionary]) {
50.         throw 'Configuration must be a JSON object.'
51.     }
52. 
53.     foreach ($key in $config.Keys) {
54.         Assert-TaskForgeConfigValue -Key $key -Value $config[$key]
55.     }
56.     return $config
57. }
58. 
59. function Write-TaskForgeConfig {
60.     param(
61.         [Parameter(Mandatory)][string]$Path,
62.         [Parameter(Mandatory)][System.Collections.IDictionary]$Config
63.     )
64. 
65.     $parent = Split-Path -Parent $Path
66.     if ($parent -and -not (Test-Path -LiteralPath $parent)) {
67.         New-Item -ItemType Directory -Path $parent -Force | Out-Null
68.     }
69. 
70.     $temporary = Join-Path $parent ".$([System.IO.Path]::GetFileName($Path)).$PID.$([guid]::NewGuid()).tmp"
71.     try {
72.         $json = ConvertTo-Json -InputObject $Config -Depth 4
73.         [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
74.         [System.IO.File]::Move($temporary, $Path, $true)
75.     }
76.     finally {
77.         if (Test-Path -LiteralPath $temporary) {
78.             Remove-Item -LiteralPath $temporary -Force
79.         }
80.     }
81. }
82. 
83. function Assert-TaskForgeConfigValue {
84.     param(
85.         [Parameter(Mandatory)][string]$Key,
86.         [Parameter(Mandatory)]$Value
87.     )
88. 
89.     switch ($Key) {
90.         'dataFile' {
91.             if ($Value -isnot [string] -or [string]::IsNullOrWhiteSpace($Value)) {
92.                 throw 'Configuration value dataFile must be a non-empty path.'
93.             }
94.         }
95.         'defaultJson' {
96.             if ($Value -isnot [bool]) {
97.                 throw 'Configuration value defaultJson must be true or false.'
98.             }
99.         }
100.         default {
101.             throw "Unknown configuration key: $Key"
102.         }
103.     }
104. }
105. 
106. function ConvertTo-TaskForgeBoolean {
107.     param(
108.         [Parameter(Mandatory)]$Value,
109.         [Parameter(Mandatory)][string]$Name
110.     )
111. 
112.     if ($Value -is [bool]) {
113.         return $Value
114.     }
115. 
116.     $text = [string]$Value
117.     if ($text.Equals('true', [System.StringComparison]::OrdinalIgnoreCase)) {
118.         return $true
119.     }
120.     if ($text.Equals('false', [System.StringComparison]::OrdinalIgnoreCase)) {
121.         return $false
122.     }
123.     throw "$Name must be true or false."
124. }
125. 
126. function Resolve-TaskForgeConfiguredPath {
127.     param(
128.         [Parameter(Mandatory)][string]$Path,
129.         [Parameter(Mandatory)][string]$ConfigFile
130.     )
131. 
132.     if ([System.IO.Path]::IsPathFullyQualified($Path)) {
133.         return [System.IO.Path]::GetFullPath($Path)
134.     }
135. 
136.     $configDirectory = Split-Path -Parent $ConfigFile
137.     return [System.IO.Path]::GetFullPath((Join-Path $configDirectory $Path))
138. }
139. 
140. function ConvertFrom-TaskForgeArguments {
141.     param([AllowEmptyCollection()][string[]]$Arguments)
142. 
143.     $options = [ordered]@{}
144.     for ($index = 0; $index -lt $Arguments.Count; $index++) {
145.         $token = $Arguments[$index]
146.         if (-not $token.StartsWith('--')) {
147.             throw "Unexpected argument: $token"
148.         }
149. 
150.         $name = $token.Substring(2)
151.         if ([string]::IsNullOrWhiteSpace($name)) {
152.             throw 'Option name cannot be empty.'
153.         }
154.         if ($options.Contains($name)) {
155.             throw "Duplicate option: --$name"
